}

/* ---------- 3. SPHERE HOVER: icon fades out before label fades in ------ */
html body .category-sphere__icon {
  transition: opacity 0.45s cubic-bezier(0.4, 0, 0.2, 1),
              filter 0.45s cubic-bezier(0.4, 0, 0.2, 1) !important;
